INSERT INTO _migration_495_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igbio_ecology_s2_001', 'topic_igcse_bio_ecology', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which organisms feed on dead organic material and release nutrients back into the soil?', 'multiple_choice', NULL, '["A. Producers such as green plants","B. Herbivores such as caterpillars","C. Decomposers such as bacteria and fungi","D. Carnivores such as hawks"]', 'C', 'Decomposers — mainly bacteria and fungi — secrete enzymes onto dead matter, digest it and release mineral ions such as nitrates back into the soil for plants to reuse. Producers make their own food by photosynthesis, while herbivores and carnivores eat living or freshly killed organisms rather than decomposing dead material. Therefore the correct answer is C: Decomposers such as bacteria and fungi.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_ecology_s2_002', 'topic_igcse_bio_ecology', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which process removes carbon dioxide from the atmosphere in the carbon cycle?', 'multiple_choice', NULL, '["A. Respiration","B. Combustion of fossil fuels","C. Decomposition","D. Photosynthesis"]', 'D', 'Green plants, algae and phytoplankton take in carbon dioxide for photosynthesis and lock the carbon into organic molecules such as glucose. Respiration, combustion and decomposition all release carbon dioxide back into the atmosphere rather than removing it. Therefore the correct answer is D: Photosynthesis.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_ecology_s2_003', 'topic_igcse_bio_ecology', 'subj_igcse_biology', 'igcse', NULL, NULL, 'In the food chain grass → grasshopper → frog → hawk, what happens to the amount of energy available at each successive trophic level?', 'multiple_choice', NULL, '["A. It decreases because energy is lost in respiration, movement and waste","B. It increases because each animal eats more than the last","C. It stays exactly the same at every level","D. It decreases only at the final trophic level"]', 'A', 'At each transfer much of the energy is used for respiration and movement or lost in waste and uneaten material, so only a small fraction passes on and the available energy decreases at every level. Energy cannot increase along a food chain, transfer is never completely efficient, and the losses happen at every step rather than only at the last. Therefore the correct answer is A: It decreases because energy is lost in respiration, movement and waste.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igbio_ecology_s2_004', 'topic_igcse_bio_ecology', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Nitrate fertiliser is washed from a field into a lake. Which sequence of events is most likely to follow?', 'multiple_choice', NULL, '["A. Clearer water → more underwater plants → more fish","B. Algal bloom → death of algae → bacterial decomposition → oxygen depletion in the water","C. Immediate death of all fish from nitrate poisoning","D. Less plant growth because nitrates are toxic to algae"]', 'B', 'The extra nitrate triggers rapid algal growth (an algal bloom); when the algae die, decomposer bacteria multiply and respire, using up the dissolved oxygen so fish and other aquatic animals suffocate. Nitrates are nutrients rather than fast-acting poisons, they promote rather than prevent algal growth, and the outcome is oxygen loss rather than clearer water. Therefore the correct answer is B: Algal bloom → death of algae → bacterial decomposition → oxygen depletion in the water.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igbio_ecology_s2_005', 'topic_igcse_bio_ecology', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which process in the nitrogen cycle returns nitrogen gas to the atmosphere?', 'multiple_choice', NULL, '["A. Nitrogen fixation by lightning","B. Nitrification by nitrifying bacteria","C. Denitrification by bacteria that convert nitrates to nitrogen gas","D. Absorption of nitrates by plant roots"]', 'C', 'Denitrifying bacteria in waterlogged soils convert nitrates back into nitrogen gas, which escapes into the atmosphere. Nitrogen fixation and nitrification move nitrogen in the opposite direction — from nitrogen gas or ammonium compounds towards nitrates — and the absorption of nitrates by roots removes nitrate from the soil rather than returning nitrogen to the atmosphere. Therefore the correct answer is C: Denitrification by bacteria that convert nitrates to nitrogen gas.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_ecology_s2_006', 'topic_igcse_bio_ecology', 'subj_igcse_biology', 'igcse', NULL, NULL, 'A lake contains pike, perch, water fleas and algae, together with the water, dissolved minerals and sunlight. Which term describes this whole system?', 'multiple_choice', NULL, '["A. A population","B. A community, with no abiotic factors","C. A single food chain","D. An ecosystem"]', 'D', 'The system includes all the living organisms interacting with one another and with the non-living factors such as water, minerals and light, which together make up an ecosystem. A population is the members of one species only, a community is all the living organisms without the non-living environment, and a food chain describes just one feeding relationship. Therefore the correct answer is D: An ecosystem.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_495_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_495_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_495_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'igcse-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_495_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'igcse-bio-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/', 0, 1 FROM _migration_495_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_495_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_495_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_495_expected e ON e.id = r.question_id WHERE r.batch_id IS 'igcse-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_495_expected e ON e.id = q.id) = 6 THEN 1 ELSE 0 END;
